// Content access. `manifest.json` (generated by scripts/build-manifest.mjs) is a light index available synchronously;
// full lessons are loaded per track on demand (code-split chunks).
import manifest from './manifest.json';

export const TRACKS = ['ar', 'sa', 'en', 'id'];
/** The language a track teaches ('sa' teaches Arabic). */
export const trackLang = (track) => (track === 'sa' ? 'ar' : track);
export const TRACK_META = {
  ar: { glyph: 'ع', color: 'var(--c-ar)' },
  sa: { glyph: 'س', color: 'var(--c-sa)' },
  en: { glyph: 'Aa', color: 'var(--c-en)' },
  id: { glyph: 'Id', color: 'var(--c-id)' },
};

export const allLessonMeta = manifest.lessons;
export const lessonsOfTrack = (track) => allLessonMeta.filter((l) => l.track === track).sort((a, b) => a.order - b.order);
export const lessonMeta = (id) => allLessonMeta.find((l) => l.id === id);
export const itemToLesson = (() => {
  const m = new Map();
  for (const l of allLessonMeta) for (const i of l.items) m.set(i, l.id);
  return m;
})();
export const allItemIds = [...itemToLesson.keys()];
export const trackOfItem = (itemId) => lessonMeta(itemToLesson.get(itemId))?.track;

const loaders = import.meta.glob('./content/*/*.json');
const cache = new Map();

export function loadTrack(track) {
  if (!cache.has(track)) {
    const entries = Object.entries(loaders).filter(([p]) => p.startsWith(`./content/${track}/`));
    const p = Promise.all(entries.map(([, load]) => load()))
      .then((mods) => mods.flatMap((m) => m.default ?? m).sort((a, b) => a.order - b.order))
      .catch((e) => {
        cache.delete(track);
        throw e;
      });
    cache.set(track, p);
  }
  return cache.get(track);
}
export async function loadLesson(id) {
  const meta = lessonMeta(id);
  if (!meta) return null;
  const lessons = await loadTrack(meta.track);
  return lessons.find((l) => l.id === id) ?? null;
}
export async function loadItems(itemIds) {
  const tracks = [...new Set(itemIds.map(trackOfItem).filter(Boolean))];
  const out = new Map();
  for (const t of tracks) {
    for (const l of await loadTrack(t)) for (const it of l.items) out.set(it.id, { item: it, lesson: l });
  }
  return out;
}
